import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Generic Typecheck Engine (plugin-engine-typecheck + plugin-engine-typecheck-nbe)","description":"","frontmatter":{"title":"Generic Typecheck Engine (`plugin-engine-typecheck` + `plugin-engine-typecheck-nbe`)","type":"adr","date":"2026-09-01T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","status":"accepted","status_note":"Accepted — completes the data-driven typecheck stage; rules are data, one NBE engine ships.","refs":["ADR-0032","ADR-0044","ADR-0052","ADR-0055"]},"headers":[],"relativePath":"handl/project/adrs/0054-generic-typecheck-engine.md","filePath":"vendored/handl/project/adrs/0054-generic-typecheck-engine.md"}'),a={name:`handl/project/adrs/0054-generic-typecheck-engine.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0054-generic-typecheck-engine-plugin-engine-typecheck-plugin-engine-typecheck-nbe" tabindex="-1">ADR-0054: Generic Typecheck Engine (<code>plugin-engine-typecheck</code> + <code>plugin-engine-typecheck-nbe</code>) <a class="header-anchor" href="#adr-0054-generic-typecheck-engine-plugin-engine-typecheck-plugin-engine-typecheck-nbe" aria-label="Permalink to “ADR-0054: Generic Typecheck Engine (plugin-engine-typecheck + plugin-engine-typecheck-nbe)”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Type rules reuse <code>Scheme</code> — <code>lang.types</code>.</strong> A rule synthesizes a node&#39;s type or checks it against an expected one; it may call judgment ops and other rules.</li><li><strong>Judgment ops are <code>Arr</code> ops</strong> (unify, quote, normalize, meta-solve, universe <code>max</code>, …), so rules compose with the same kernel as <code>lang.eval</code>.</li><li><strong><code>plugin-engine-typecheck</code> is the abstraction crate</strong> — marker, <code>TypecheckRequest</code>, <code>TypecheckEngine</code>; no engine code, mirroring lex/parse/eval.</li><li><strong><code>plugin-engine-typecheck-nbe</code> implements <code>TypecheckEngine</code>.</strong> NBE — <code>unify</code>, <code>quote</code>/<code>normalize</code>, metavariable solving, universe <code>max</code> — is the implementation behind the trait, not the interface.</li><li><strong>Typecheck is wired on <code>RuntimeHandle</code> (pure path).</strong> Types are values, so checking normalizes through the eval engine and depends on a bound <code>EvalEngine</code>, symmetric with the other stages.</li><li><strong><code>plugin-lib-lang-typecheck</code> is the meta leaf</strong> exposing <code>typecheck.typecheck(lang, ast)</code>, like the lex/parse/eval leaves.</li><li><strong>Rules are authored data</strong> in <code>crates/handl-kit-data-canonical/data/types.yaml</code>, included into <code>lang.types</code> as <code>eval.yaml</code> feeds <code>lang.eval</code>.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The typechecker was a Rust <code>match</code> engine: every rule was a code arm, so a new engine or language change meant editing the engine. Types are values (ADR-0032) and language is data (ADR-0044): rules belong in <code>types.yaml</code>, the algorithm behind a trait. This moves dispatch, not theory.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Change the dependent-type theory</strong> — universes, Pi/Sigma/Forall, equality and membership are unchanged.</li><li><strong>Promise a second engine</strong> — the trait makes one possible; one ships.</li><li><strong>Define the full <code>types.yaml</code> rule set</strong> — implementation work; this fixes the op set and the seam.</li><li><strong>Add spread/param destructuring to the AST</strong> — separate AST/grammar/eval work.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Every type rule is data; a new engine is a trait impl, not a rewrite.</li><li><code>types.yaml</code> becomes the review surface for typing — editable without Rust and shared by every engine; typecheck still runs eval to normalize.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/plugin-engine-typecheck/</code> — marker, request, engine trait.</li><li><code>crates/plugin-engine-typecheck-nbe/</code> — the NBE implementation.</li><li><code>crates/handl-kit-data-canonical/data/types.yaml</code> — the authored rules.</li><li><code>crates/plugin-lib-lang-typecheck/</code> — <code>typecheck.typecheck(lang, ast)</code>.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The mechanism, op set, context notes and trade-offs: <a href="./../design/0054-generic-typecheck-engine.html"><code>design/0054-generic-typecheck-engine.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};